// Verus program: reverse an array of i32s
// Build a new Vec with the same length, where a_rev[i] == a[n-1-i].

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev.len() == a.len(),
        forall|i: int|
            0 <= i < a.len() ==> a[i] == a_rev[(a.len() - 1 - i) as int],
{
    let mut out: Vec<i32> = Vec::new();
    let n: usize = a.len();
    let mut i: usize = 0;

    while i < n
        invariant
            out.len() == i,
            n == a.len(),
            forall|j: int|
                0 <= j < i ==> out[j] == a[(n - 1 - j as usize) as int],
    {
        // Push next reversed element
        out.push(a[n - 1 - i]);
        i += 1;
    }

    out
}

} // verus!